@namespace sv_62b7f909e43a4896befcd61c38bcec48.Components.Pages.Apply

<nav class="d-flex justify-content-between align-items-center mb-4 px-2">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var isFuture = !isCompleted && !isCurrent;

        <div class="text-center flex-fill position-relative">
            @if (step > 0)
            {
                <div class="position-absolute top-50 start-0 translate-middle-y"
                     style="width:50%; height:2px; left:0; z-index:0;"
                     class="@(CompletedSteps.Contains(step - 1) || CompletedSteps.Contains(step) || isCurrent ? "bg-primary" : "bg-secondary opacity-25")">
                </div>
            }
            @if (step < StepNames.Count - 1)
            {
                <div class="position-absolute top-50 translate-middle-y"
                     style="width:50%; height:2px; right:0; left:50%; z-index:0;"
                     class="@(isCompleted ? "bg-primary" : "bg-secondary opacity-25")">
                </div>
            }

            <div class="position-relative" style="z-index:1;">
                @if (isCompleted)
                {
                    <button class="btn btn-primary rounded-circle d-inline-flex align-items-center justify-content-center"
                            style="width:36px; height:36px; font-size:0.85rem;"
                            @onclick="() => OnStepClicked.InvokeAsync(step)">
                        ✓
                    </button>
                }
                else if (isCurrent)
                {
                    <span class="btn btn-primary rounded-circle d-inline-flex align-items-center justify-content-center"
                          style="width:36px; height:36px; font-size:0.85rem;">
                        @(step + 1)
                    </span>
                }
                else
                {
                    <span class="btn btn-outline-secondary rounded-circle d-inline-flex align-items-center justify-content-center opacity-50"
                          style="width:36px; height:36px; font-size:0.85rem;">
                        @(step + 1)
                    </span>
                }
            </div>
            <div class="small mt-1 @(isFuture ? "text-muted opacity-50" : isCurrent ? "fw-bold text-primary" : "text-success")">
                @StepNames[step]
            </div>
        </div>
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

